# The api-version the Microsoft.Resources calls were captured with in the recordings below.
RECORDED_RESOURCES_API_VERSION = '2022-09-01'

# Resource-provider registration endpoints hit by register_providers_if_needed().
RP_REGISTRATION_PATH = re.compile(
    r'^/subscriptions/[^/]+/providers/'
    r'Microsoft\.(HybridConnectivity|AwsConnector|HybridCompute)(/register)?$',
    re.IGNORECASE
)


class ResourceProviderApiVersionProcessor(RecordingProcessor):
    """Pin the Microsoft.Resources api-version used by the RP registration pre-check.

    Every command in this extension calls ``register_providers_if_needed``, which talks to
    Microsoft.Resources through ``ResourceType.MGMT_RESOURCE_RESOURCES``. That api-version is
    pinned by azure-cli-core, not by this extension, so it drifts whenever core bumps it and
    the recorded requests stop matching -- failing every test here for reasons unrelated to
    the change under test. Normalising it on replay keeps the recordings matchable; the
    responses are still the ones that were actually recorded.
    """

    def process_request(self, request):
        parsed = urlparse(request.uri)
        if RP_REGISTRATION_PATH.match(parsed.path):
            query = parse_qs(parsed.query)
            if 'api-version' in query:
                query['api-version'] = [RECORDED_RESOURCES_API_VERSION]
                request.uri = urlunparse(parsed._replace(query=urlencode(query, doseq=True)))
        return request


