        connector_name = "testGcpConnector"
        self.kwargs.update({
            'name': f'{connector_name}',
            'rg': resource_group,
            'sub': f'{sub}',
            'loc': 'eastus',
            # projectProperties and organizationProperties are mutually exclusive (service-side
            # rule, not expressed in the swagger). Use the organization profile here so the
            # exclusion-list update below applies to the same connector.
            'profile': '{organization-properties:{organization-id:123456789123,'
                       'management-project-number:123456789124,'
                       'management-project-id:my-management-project}}',
        })

        # test public-cloud-connector create with a GCP cloud profile
        self.cmd(
            'arc-multicloud public-cloud-connector create '
            '--name {name} '
            '--resource-group {rg} '
            '--subscription {sub} '
            '--host-type GCP '
            '--gcp-cloud-profile "{profile}" '
            '--location {loc}',
            checks=[self.check('name', 'testGcpConnector'),
                    self.check('kind', 'GCP'),
                    self.check('properties.hostType', 'GCP'),
                    self.check(
                        'properties.gcpCloudProfile.organizationProperties.organizationId',
                        '123456789123')]
        )

        self.kwargs.update({
            # generate-gcp-template takes connectorId in the request body, so it must be a
            # fully-qualified ARM resource ID (leading '/'), unlike the scope-style connector
            # ID that solution-configuration interpolates into the request path.
            'cid': f'/subscriptions/{sub}/resourceGroups/{resource_group}/providers/Microsoft.HybridConnectivity/publicCloudConnectors/{connector_name}',
            'update_profile': '{organization-properties:{excluded-project-numbers:[123456789125],'
                              'excluded-folder-ids:[folder-1]}}',
        })

        # test public-cloud-connector update of the GCP organization exclusion lists
        self.cmd(
            'arc-multicloud public-cloud-connector update '
            '--name {name} '
            '--resource-group {rg} '
            '--subscription {sub} '
            '--gcp-cloud-profile "{update_profile}"',
            checks=[
                self.check('name', 'testGcpConnector'),
                # the exclusion lists are the only updatable GCP fields: assert they persist
                self.check(
                    'properties.gcpCloudProfile.organizationProperties.excludedProjectNumbers',
                    ['123456789125']),
                self.check(
                    'properties.gcpCloudProfile.organizationProperties.excludedFolderIds',
                    ['folder-1']),
                # and that the immutable organization fields survived the patch
                self.check(
                    'properties.gcpCloudProfile.organizationProperties.organizationId',
                    '123456789123'),
            ]
        )

        # a solution configuration is required before a template can be generated: the service
        # reads the solution types from the connector and rejects them in the request body
        self.cmd(
            'arc-multicloud solution-configuration create '
            '--connector-id {cid} '
            '--name assetmgmt '
            '--solution-type "Microsoft.AssetManagement" '
            '--solution-settings periodicSync="true" periodicSyncTime="1"',
            checks=[self.check('properties.solutionType', 'Microsoft.AssetManagement')]
        )

        # test generate-gcp-template, writing into a scratch directory so the generated
        # artifact itself can be asserted on rather than just the success envelope
        template_dir = self.create_temp_dir()
        self.kwargs.update({'outdir': template_dir})
        self.cmd(
            'arc-multicloud generate-gcp-template '
            '--connector-id {cid} '
            '--subscription {sub} '
            '--gcp-template-format terraform '
            '--output-directory "{outdir}"',
            checks=[self.check('status', 'success')]
        )

        # the command reports success before writing the file, so assert the artifact landed
        # on disk and is well-formed JSON
        template_path = os.path.join(template_dir, 'gcp_template.json')
        self.assertTrue(
            os.path.isfile(template_path),
            f'generate-gcp-template reported success but wrote no file to {template_path}')
        with open(template_path) as template_file:
            self.assertIsInstance(json.load(template_file), dict)

        # the write happens in _output, after a successful service call, so a write failure
        # must surface as a command failure rather than a success envelope with a nonzero
        # exit swallowed. Point --output-directory at an existing *file*: the directory
        # check passes, and opening a path beneath a file fails on every platform.
        self.kwargs.update({'badoutdir': template_path})
        self.cmd(
            'arc-multicloud generate-gcp-template '
            '--connector-id {cid} '
            '--subscription {sub} '
            '--gcp-template-format terraform '
            '--output-directory "{badoutdir}"',
            expect_failure=True
        )

        # test public-cloud-connector delete
        self.cmd(
            'arc-multicloud public-cloud-connector delete '
            '--name {name} '
            '--resource-group {rg} '
            '--subscription {sub} '
            '-y'
        )

